/**
 * Builder class for REST resources.
 */
export class Resource {
  constructor(httpClient, name, options = {}) {
    this.httpClient = httpClient;
    this.resourceName = name;
    this.resourceId = options.resourceId ?? null;
    this.subPaths = options.subPaths ? [...options.subPaths] : [];
    this.queryParams = options.queryParams ? { ...options.queryParams } : {};
    this.customHeaders = options.customHeaders ? { ...options.customHeaders } : {};
    this.isSafe = options.isSafe ?? false;
    this.requestTimeout = options.requestTimeout ?? null;
    this.abortSignal = options.abortSignal ?? null;
    this.progressCallback = options.progressCallback ?? null;
    this.cacheOptions = options.cacheOptions ?? null;
  }

  _clone(overrides = {}) {
    return new Resource(this.httpClient, this.resourceName, {
      resourceId: this.resourceId,
      subPaths: this.subPaths,
      queryParams: this.queryParams,
      customHeaders: this.customHeaders,
      isSafe: this.isSafe,
      requestTimeout: this.requestTimeout,
      abortSignal: this.abortSignal,
      progressCallback: this.progressCallback,
      cacheOptions: this.cacheOptions,
      ...overrides,
    });
  }

  /**
   * Enables safe mode for the request.
   * Instead of throwing, it returns { data, error, ok, status, headers }.
   */
  safe() {
    return this._clone({ isSafe: true });
  }

  /**
   * Sets the ID for the resource.
   */
  id(val) {
    return this._clone({ resourceId: val });
  }

  /**
   * Sets a sub-resource path. Can be called multiple times for nested resources.
   */
  sub(path) {
    return this._clone({ subPaths: [...this.subPaths, path] });
  }

  /**
   * Sets query parameters.
   */
  query(params) {
    return this._clone({ queryParams: { ...this.queryParams, ...params } });
  }

  /**
   * Sets custom request headers.
   */
  headers(headers) {
    return this._clone({ customHeaders: { ...this.customHeaders, ...headers } });
  }

  /**
   * Sets a timeout in milliseconds for this request.
   */
  timeout(ms) {
    return this._clone({ requestTimeout: ms });
  }

  /**
   * Connects an AbortSignal for request cancellation.
   */
  signal(abortSignal) {
    return this._clone({ abortSignal });
  }

  /**
   * Sets an upload progress tracking callback.
   */
  onProgress(fn) {
    return this._clone({ progressCallback: fn });
  }

  /**
   * Enables in-memory caching for GET requests.
   * @param {number|object} options - TTL in ms or { ttl, key }
   */
  cache(options = {}) {
    const ttl = typeof options === 'number' ? options : (options.ttl ?? 5000);
    const key = typeof options === 'object' ? options.key : null;
    return this._clone({ cacheOptions: { ttl, key } });
  }

  /**
   * Builds the full URL path.
   */
  buildUrl() {
    const isAbsolute = typeof this.resourceName === 'string' &&
      (this.resourceName.startsWith('http://') || this.resourceName.startsWith('https://') || this.resourceName.startsWith('//'));

    if (isAbsolute) {
      let url = this.resourceName;
      const extraSegments = [];
      if (this.resourceId !== null && this.resourceId !== undefined) {
        extraSegments.push(String(this.resourceId));
      }
      extraSegments.push(...this.subPaths);

      if (extraSegments.length > 0) {
        const cleanSub = extraSegments.join('/').split('/').filter(Boolean).join('/');
        url = url.endsWith('/') ? `${url}${cleanSub}` : `${url}/${cleanSub}`;
      }
      return url;
    }

    const segments = [this.resourceName];
    if (this.resourceId !== null && this.resourceId !== undefined) {
      segments.push(String(this.resourceId));
    }
    segments.push(...this.subPaths);

    const cleanPath = segments
      .join('/')
      .split('/')
      .filter(Boolean)
      .join('/');

    return `/${cleanPath}`;
  }

  /**
   * Internal request executor.
   */
  async _execute(config) {
    const url = this.buildUrl();
    const method = (config.method || 'GET').toUpperCase();

    const requestConfig = {
      ...config,
      url,
      params: this.queryParams,
      headers: {
        ...(config.headers || {}),
        ...this.customHeaders,
      },
    };

    if (this.requestTimeout) requestConfig.timeout = this.requestTimeout;
    if (this.abortSignal) requestConfig.signal = this.abortSignal;
    if (this.progressCallback) {
      requestConfig.onUploadProgress = (progressEvent) => {
        const percent = progressEvent.total
          ? Math.round((progressEvent.loaded * 100) / progressEvent.total)
          : 0;
        this.progressCallback({
          loaded: progressEvent.loaded,
          total: progressEvent.total,
          percent,
          event: progressEvent,
        });
      };
    }

    // Check cache for GET requests
    let cacheKey = null;
    if (method === 'GET' && this.cacheOptions && this.httpClient.getCache) {
      cacheKey = this.cacheOptions.key || `${url}?${new URLSearchParams(this.queryParams).toString()}`;
      const cached = this.httpClient.getCache(cacheKey);
      if (cached) {
        if (!this.isSafe) return cached.rawResponse;
        return { ...cached.safeResponse };
      }
    }

    if (!this.isSafe) {
      const response = await this.httpClient.request(requestConfig);
      if (cacheKey) {
        this.httpClient.setCache(cacheKey, { rawResponse: response, safeResponse: null }, this.cacheOptions.ttl);
      }
      return response;
    }

    try {
      const response = await this.httpClient.request(requestConfig);
      const safeResult = {
        data: response.data,
        status: response.status,
        ok: true,
        error: null,
        headers: response.headers,
      };
      if (cacheKey) {
        this.httpClient.setCache(cacheKey, { rawResponse: response, safeResponse: safeResult }, this.cacheOptions.ttl);
      }
      return safeResult;
    } catch (error) {
      return {
        data: null,
        status: error.response?.status || 0,
        ok: false,
        error: error.response?.data || error.message,
        headers: error.response?.headers || null,
      };
    }
  }

  // --- CRUD HTTP methods ---

  async get() {
    return this._execute({ method: 'GET' });
  }

  async post(data) {
    return this._execute({ method: 'POST', data });
  }

  async put(data) {
    return this._execute({ method: 'PUT', data });
  }

  async patch(data) {
    return this._execute({ method: 'PATCH', data });
  }

  async delete() {
    return this._execute({ method: 'DELETE' });
  }

  /**
   * Helper for uploading data/FormData with progress tracking.
   */
  async upload(data, method = 'POST') {
    return this._execute({ method, data });
  }

  /**
   * Async iterator for iterating through paginated resources.
   */
  async *paginate({
    limit = 10,
    pageParam = 'page',
    limitParam = 'limit',
    startPage = 1,
    extractItems = (res) => {
      const data = res?.data ?? res;
      if (Array.isArray(data)) return data;
      if (data && Array.isArray(data.items)) return data.items;
      if (data && Array.isArray(data.data)) return data.data;
      if (data && Array.isArray(data.results)) return data.results;
      return [];
    },
  } = {}) {
    let currentPage = startPage;

    while (true) {
      const resourceWithQuery = this.query({
        [pageParam]: currentPage,
        [limitParam]: limit,
      });

      const response = await resourceWithQuery.get();
      const items = extractItems(response);

      if (!items || items.length === 0) {
        break;
      }

      yield {
        page: currentPage,
        items,
        rawResponse: response,
      };

      if (items.length < limit) {
        break;
      }

      currentPage++;
    }
  }
}


